<?php declare(strict_types=1);

namespace Shef\ToolsAiAnnounce\Announce;

/**
 * Картинки окна объявления (1.5.0): встроенный SVG, три — с анимацией CSS
 * (стройка, собрание, библиотека). Поле объявления art: пусто — по виду
 * окна (byLayout()). Своя картинка (image) и видео — важнее.
 *
 * Анимации — только transform и opacity, при «уменьшить движение» в
 * системе (prefers-reduced-motion) стоят. Текст в SVG — свой, не из
 * объявления: подстановки нет.
 *
 * Чистый класс — tests/art_test.php. Черновик правим целиком здесь.
 */
final class Art
{
	/** Код => название для формы; пусто — по виду окна. */
	public const ARTS = [
		'' => 'по виду окна',
		'news' => 'новинка',
		'build' => 'стройка (анимация)',
		'meeting' => 'собрание (анимация)',
		'library' => 'библиотека (анимация)',
		'bell' => 'колокольчик',
		'alert' => 'предупреждение',
		'congrats' => 'поздравление',
	];

	/** Вид окна => картинка по умолчанию. */
	public const BY_LAYOUT = ['cosmos' => 'news', 'important' => 'bell', 'danger' => 'alert', 'congrats' => 'congrats'];

	/** Картинка объявления: своя из поля art или по виду окна. */
	public static function pick(array $item): string
	{
		$art = (string)($item['art'] ?? '');

		return $art !== '' && isset(self::ARTS[$art]) ? $art : (self::BY_LAYOUT[(string)($item['layout'] ?? '')] ?? 'news');
	}

	/** SVG картинки; неизвестный код — новинка. */
