	/** Стили анимаций (классы sa-*). */
	public static function css(): string
	{
		return '.sa *{transform-box:fill-box}.sa-float{animation:saFloat 3.2s ease-in-out infinite}@keyframes saFloat{50%{transform:translateY(-6px)}}.sa-tap{animation:saTap 2.6s ease-in-out infinite;transform-origin:left top}@keyframes saTap{0%,100%{transform:translate(0,0)}45%{transform:translate(-14px,-10px)}55%{transform:translate(-14px,-10px) scale(.88)}}.sa-ring{transform-origin:50% 0;animation:saRing 2.4s ease-in-out infinite}@keyframes saRing{0%,60%,100%{transform:rotate(0)}10%{transform:rotate(12deg)}20%{transform:rotate(-10deg)}30%{transform:rotate(7deg)}40%{transform:rotate(-4deg)}}.sa-wave{animation:saWave 2.4s ease-out infinite;opacity:0}.sa-wave.sa-d2{animation-delay:.25s}@keyframes saWave{5%{opacity:0}15%{opacity:1}55%,100%{opacity:0}}.sa-pulse{transform-origin:50% 60%;animation:saPulse 1.8s ease-in-out infinite}@keyframes saPulse{50%{transform:scale(1.06)}}.sa-blink{animation:saBlink 1s steps(2) infinite}@keyframes saBlink{50%{opacity:.25}}.sa-conf{animation:saFall 5s linear infinite}@keyframes saFall{from{transform:translateY(0)}to{transform:translateY(230px)}}.sa-twinkle{transform-origin:center;animation:saTw 1.6s ease-in-out infinite}@keyframes saTw{50%{opacity:.3;transform:scale(.7)}}.sa-dozer{animation:saDrive 6s ease-in-out infinite}@keyframes saDrive{0%,100%{transform:translateX(0)}50%{transform:translateX(70px)}}.sa-wheel{transform-origin:center;animation:saSpin 1.2s linear infinite}@keyframes saSpin{to{transform:rotate(360deg)}}.sa-dust{transform-origin:center;animation:saDust 1.2s ease-out infinite}@keyframes saDust{0%{opacity:.8;transform:scale(.5)}100%{opacity:0;transform:scale(1.6) translateX(-10px)}}.sa-hook{animation:saHook 3s ease-in-out infinite}@keyframes saHook{50%{transform:translateY(10px)}}.sa-cloud{animation:saCloud 14s linear infinite}@keyframes saCloud{50%{transform:translateX(60px)}}.sa-bar{transform-origin:bottom;animation:saBar 3.6s ease-in-out infinite}.sa-d1{animation-delay:.2s}.sa-d2{animation-delay:.4s}.sa-d3{animation-delay:.6s}@keyframes saBar{0%,100%{transform:scaleY(.35)}40%,70%{transform:scaleY(1)}}.sa-say{transform-origin:80% 100%;animation:saSay 4s ease-in-out infinite}.sa-say.sa-late{animation-delay:2s;transform-origin:20% 100%}@keyframes saSay{0%,45%,100%{opacity:0;transform:scale(.6)}8%,38%{opacity:1;transform:scale(1)}}.sa-dot{animation:saDot 1s ease-in-out infinite}@keyframes saDot{50%{transform:translateY(-4px)}}.sa-pull{animation:saPull 4s ease-in-out infinite}.sa-pull.sa-late{animation-delay:2s}@keyframes saPull{0%,60%,100%{transform:translateY(0)}20%,40%{transform:translateY(-12px)}}.sa-page{transform-origin:left center;animation:saPage 3.2s ease-in-out infinite}@keyframes saPage{0%,15%{transform:scaleX(1)}50%,65%{transform:scaleX(-1)}100%{transform:scaleX(1)}}.sa-rise text{animation:saRise 3.2s ease-out infinite;opacity:0}.sa-rise .sa-d1{animation-delay:1s}.sa-rise .sa-d2{animation-delay:2s}@keyframes saRise{10%{opacity:1}100%{opacity:0;transform:translateY(-34px)}}.sa-glow{animation:saGlow 3s ease-in-out infinite}@keyframes saGlow{50%{opacity:.7}}@media (prefers-reduced-motion:reduce){.sa *{animation:none!important;opacity:1}}';
	}
